// ═══ WHY volatile counter++ FAILS ═══
volatile int counter = 0;
// Thread-1: LOAD counter(0) → ADD 1 → STORE counter(1)
// Thread-2: LOAD counter(0) → ADD 1 → STORE counter(1) ← SAME result!
// Expected: 2. Actual: 1. Thread-2 read stale value before Thread-1 wrote.
// volatile ensures LOAD reads from memory and STORE writes to memory
// but doesn't prevent another thread from LOADing between LOAD and STORE!

// ═══ FIX 1: AtomicInteger — CAS (best for low-medium contention) ═══
AtomicInteger counter = new AtomicInteger(0);
counter.incrementAndGet();
// Internally: do { old = get(); } while (!compareAndSet(old, old+1));
// CAS: "set to old+1 ONLY IF current value is still old"
// If another thread changed it → CAS fails → retry with new value!
// Lock-free! No blocking! Thread-safe!

// ═══ FIX 2: synchronized (simple but slower) ═══
int counter = 0;
synchronized (lock) { counter++; }  // only ONE thread increments at a time

// ═══ FIX 3: LongAdder — best for HIGH contention ═══
LongAdder counter = new LongAdder();
counter.increment();   // each thread updates its OWN cell (no contention!)
counter.sum();         // sums all cells (slightly stale during concurrent increments)
// Under 64 threads: LongAdder is 10x faster than AtomicLong!
// Trade-off: sum() may not reflect in-flight increments

// ═══ PERFORMANCE COMPARISON (64 threads, 1M increments each) ═══
// volatile int + sync:     ~2000ms (lock contention)
// AtomicInteger:           ~800ms (CAS retries under contention)
// LongAdder:               ~100ms (per-thread cells, minimal contention!)
