package com.bank.counter;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class CounterSafetyTest {

    static final int THREADS = 100;
    static final int INCREMENTS = 10_000;
    static final int EXPECTED = THREADS * INCREMENTS;

    // ═══ UNSAFE: volatile counter++ ═══
    @Test
    void volatileCounter_losesIncrements() throws InterruptedException {
        int[] counter = {0};
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) counter[0]++;
                latch.countDown();
            }).start();
        }
        latch.await();

        System.out.println("volatile: " + counter[0] + " / " + EXPECTED);
        // Almost always < 1,000,000. Lost thousands of increments!
    }

    // ═══ FIX 1: AtomicInteger ═══
    @Test
    void atomicInteger_exact() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) counter.incrementAndGet();
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter.get()).isEqualTo(EXPECTED);  // exact!
    }

    // ═══ FIX 2: LongAdder (fastest under contention) ═══
    @Test
    void longAdder_exact() throws InterruptedException {
        LongAdder counter = new LongAdder();
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) counter.increment();
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter.sum()).isEqualTo(EXPECTED);  // exact!
    }

    // ═══ FIX 3: synchronized ═══
    @Test
    void synchronized_exact() throws InterruptedException {
        int[] counter = {0};
        Object lock = new Object();
        CountDownLatch latch = new CountDownLatch(THREADS);

        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) {
                    synchronized (lock) { counter[0]++; }
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter[0]).isEqualTo(EXPECTED);  // exact!
    }

    // ═══ PERFORMANCE BENCHMARK ═══
    @Test
    void performance_comparison() throws InterruptedException {
        // AtomicInteger
        AtomicInteger ai = new AtomicInteger(0);
        long t1 = System.nanoTime();
        CountDownLatch l1 = new CountDownLatch(THREADS);
        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) ai.incrementAndGet();
                l1.countDown();
            }).start();
        }
        l1.await();
        long atomicMs = (System.nanoTime() - t1) / 1_000_000;

        // LongAdder
        LongAdder la = new LongAdder();
        long t2 = System.nanoTime();
        CountDownLatch l2 = new CountDownLatch(THREADS);
        for (int t = 0; t < THREADS; t++) {
            new Thread(() -> {
                for (int i = 0; i < INCREMENTS; i++) la.increment();
                l2.countDown();
            }).start();
        }
        l2.await();
        long adderMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("AtomicInteger: " + atomicMs + "ms, LongAdder: " + adderMs + "ms");
        // LongAdder typically 2-5x faster under high contention!
    }
}
